class SurfaceTrail:
    """Where you have driven, walked or flown low on the body you are over, this visit (explorer ideas, item 1, from
    Rhino Surface Mapper's idea): Status.json's position each tick (State.surface_here), a point after moving
    TRAIL_STEP_M, at most TRAIL_MAX (the older half thinned by half when full). Another body, or none (you left its
    orbit, a jump), starts afresh. Live only, in memory: a restart starts a new trail."""
    TRAIL_STEP_M = 20.0
    TRAIL_MAX = 2000
    TRAIL_SENT = 300   # points the payload carries (evenly picked, the newest always)

    def __init__(self):
        self.key, self.pts = None, []

    def note(self, h):
        """h: State.surface_here() (None away from a body)."""
        if not h or h.get("lat") is None or h.get("lon") is None:
            self.key, self.pts = None, []
            return
        key = (h["system"], h["body_id"])
        if key != self.key:
            self.key, self.pts = key, []
        if self.pts and surface_m(self.pts[-1][0], self.pts[-1][1], h["lat"], h["lon"], h["radius"]) < self.TRAIL_STEP_M:
            return
        self.pts.append((round(h["lat"], 5), round(h["lon"], 5)))
        if len(self.pts) > self.TRAIL_MAX:
            half = len(self.pts) // 2
            self.pts = self.pts[:half:2] + self.pts[half:]

    def points(self, key):
        """[[lat, lon], ...] for the body `key` (system, body_id), at most TRAIL_SENT: [] for another body."""
        if key != self.key or len(self.pts) < 2:
            return []
        pts = self.pts
        if len(pts) > self.TRAIL_SENT:
            step = len(pts) / self.TRAIL_SENT
            pts = [pts[int(i * step)] for i in range(self.TRAIL_SENT - 1)] + [pts[-1]]
        return [list(p) for p in pts]


class ScoopWatch:
    """Fuel scooping from Status.json, polled every tick: the end of each scoop, once. The flag must stay off
    SCOOP_SETTLE s (it flickers at the edge of the scoop zone) and the scoop must have run SCOOP_MIN_RUN s.
    A scoop cut short by a jump (FSD charging, or a hyperspace StartJump just now) says nothing, and nor does
    one whose tank capacity is unknown (no Loadout yet)."""

    # the seconds to a full tank while scooping (the author's choice, 2026-10-25: from Route Scoop's idea): the fuel's
    # rise over the last SCOOP_RATE_WINDOW s of Status.json readings (the rate falls off with the distance from the
    # star, so a short window follows it); the journal's FuelScoop comes every 5 t and at the end: too seldom
    SCOOP_RATE_WINDOW = 8.0
    SCOOP_RATE_MIN_S = 2.0

    def __init__(self):
        self.start = self.off_since = None
        self.jumping = False
        self.samples = []   # (when, fuel) while the flag is on, the last SCOOP_RATE_WINDOW s

    def to_full(self, capacity):
        """Seconds until the tank is full at the scoop's current rate, while scooping; None when not scooping, the
        rate is not known yet (under SCOOP_RATE_MIN_S of readings, or the fuel not rising) or the tank is full."""
        if self.start is None or self.off_since is not None or not capacity or len(self.samples) < 2:
            return None
        (t0, f0), (t1, f1) = self.samples[0], self.samples[-1]
        if t1 - t0 < self.SCOOP_RATE_MIN_S or f1 <= f0 or f1 >= capacity - 0.05:
            return None
        return max(1, round((capacity - f1) / ((f1 - f0) / (t1 - t0))))

    def update(self, st, capacity, now, jump_ts=None):
        """-> {"pct", "full"} when a scoop has just ended, else None."""
        st = st or {}
        if not st.get("live"):
            self.start = self.off_since = None
            return None
        flags = st.get("flags") or 0
        if flags & FLAG_SCOOPING:
            if self.start is None:
                self.start = now
                self.samples = []
            fuel = st.get("fuel_main")
            if isinstance(fuel, (int, float)) and (not self.samples or fuel != self.samples[-1][1]):
                self.samples.append((now, fuel))
                self.samples = [x for x in self.samples if now - x[0] <= self.SCOOP_RATE_WINDOW]
            # scooping again: a charge seen during a flicker was cancelled (a real jump ends the scoop for good)
            self.off_since, self.jumping = None, False
            return None
        if self.start is None:
            return None
        if flags & (FLAG_FSD_CHARGING | FLAG_FSD_JUMP):
            self.jumping = True
        if self.off_since is None:
            self.off_since = now
            return None
        if now - self.off_since < SCOOP_SETTLE:
            return None
        ran, self.start, self.off_since = self.off_since - self.start, None, None
        fuel = st.get("fuel_main")
        if ran < SCOOP_MIN_RUN or not capacity or fuel is None:
            return None
        try:
            jumped = self.jumping or (jump_ts is not None and 0 <= now - ts_seconds(jump_ts) <= SCOOP_JUMP_GRACE + SCOOP_SETTLE)
        except (TypeError, ValueError):
            jumped = self.jumping
        full = fuel >= capacity - 0.05
        if not full and jumped:
            return None
        return {"pct": min(100, round(100 * fuel / capacity)), "full": full}


def tags_shown(tags, cap=BIO_TAGS_SHOWN):
    """The tagged plants the payload sends (bio_tags_here's, nearest first): each species' nearest usable tag always
    (the map keeps it, at the rim when far: Kurbo26, 2026-10-16), then the nearest of the rest up to `cap`, nearest
    first. Only the nearest `cap` lost a species beyond them (sweep 2026-10-16)."""
    keep, seen = set(), set()
    for i, t in enumerate(tags):
        if t.get("usable") and t.get("species") not in seen:
            seen.add(t.get("species"))
            keep.add(i)
    for i in range(len(tags)):
        if len(keep) >= cap:
            break
        keep.add(i)
    return [t for i, t in enumerate(tags) if i in keep]


def fire_group_letter(group):
    """Status.json FireGroup (0, 1, ...) as the letter the game shows (A, B, ...); None when unknown."""
    return chr(65 + group) if isinstance(group, int) and not isinstance(group, bool) and 0 <= group < 26 else None


def simulate_settings(st):
    """--simulate (screenshots and demos): the settings with the co-pilot button and the clipboard off."""
    return dict(st, copilot=dict(st["copilot"], enabled=False), highway=dict(st["highway"], clipboard=False))


def simulate_keyboard_off(honker, why="--simulate"):
    """--simulate, and a server away from the game PC: no virtual keyboard at all, so every open, press, test and
    auto-target run is refused (nothing may press a key into whatever window has focus)."""
    honker.evdev, honker.status = None, f"off ({why})"
    honker.off_why = why   # auto honk's readiness check says so rather than "evdev is not installed" (S69)
    return honker


