# any optional slot). Hardpoints and utilities are left out: noise for an explorer.
CORE_SLOTS = {"FrameShiftDrive": "FSD", "PowerPlant": "Power plant", "MainEngines": "Thrusters",
              "LifeSupport": "Life support", "Radar": "Sensors"}
